/**
 * Running text with marks (D73, D91 C2a; spec/02 §3.1b): every range of [marks] gets the mark fill behind its
 * characters, from the font's ascent to its descent, and the 2 dp mark edge right under them (the edge carries the
 * shape); [current], the current search hit, takes a 3 dp edge in text instead. Per line of a wrapped range; the text
 * keeps its width. The caller says „Treffer 1 von 2“ in words.
 */
@Composable
fun SbMarkedText(
    text: String,
    marks: List<IntRange>,
    modifier: Modifier = Modifier,
    current: IntRange? = null,
    style: TextStyle = SebaroTheme.typography.body,
    color: Color = SebaroTheme.colors.text,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val mark = SebaroTheme.mark
    val density = LocalDensity.current
    val typeface by LocalFontFamilyResolver.current.resolve(
        style.fontFamily,
        style.fontWeight ?: FontWeight.Normal,
        style.fontStyle ?: FontStyle.Normal,
        FontSynthesis.All,
    )
    // ascent (negative) and descent of the resolved face: the box the web's <mark> fills
    val metrics = remember(typeface, style.fontSize, density) {
        Paint().apply {
            (typeface as? Typeface)?.let { this.typeface = it }
            textSize = with(density) { style.fontSize.toPx() }
        }.fontMetrics
    }
    var layout by remember { mutableStateOf<TextLayoutResult?>(null) }
    Text(
        text,
        modifier.drawBehind {
            val l = layout ?: return@drawBehind
            fun draw(range: IntRange, edge: Color, edgeWidth: Float) {
                val start = range.first.coerceIn(0, text.length)
                val end = (range.last + 1).coerceIn(0, text.length)
                if (start >= end) return
                for (line in l.getLineForOffset(start)..l.getLineForOffset(end - 1)) {
                    val from = maxOf(start, l.getLineStart(line))
                    val to = minOf(end, l.getLineEnd(line, visibleEnd = true))
                    if (from >= to) continue
                    val x1 = l.getHorizontalPosition(from, usePrimaryDirection = true)
                    // the far edge of the last marked character on this line: where a word breaks inside itself,
                    // the offset `to` already starts the next line, so its position would be that line's start
                    val last = l.getBoundingBox(to - 1)
                    val x2 = if (l.getBidiRunDirection(to - 1) == ResolvedTextDirection.Rtl) last.left else last.right
                    val top = l.getLineBaseline(line) + metrics.ascent
                    val bottom = l.getLineBaseline(line) + metrics.descent
                    val left = minOf(x1, x2)
                    val width = maxOf(x1, x2) - left
                    drawRect(mark.fill, Offset(left, top), Size(width, bottom - top))
                    drawRect(edge, Offset(left, bottom), Size(width, edgeWidth))
                }
            }
            marks.forEach { if (it != current) draw(it, mark.edge, t.x.markEdgeWidth.toPx()) }
            current?.let { draw(it, c.text, t.borderWidth.strong.toPx()) }
        },
        style = style,
        color = color,
        onTextLayout = { layout = it },
    )
}
